// ==UserScript==
// @name         优学院助手 · 纳西妲主题美化
// @namespace    https://github.com/BrocadeHutHost
// @version      5.6.0
// @description  为「优学院助手 + 文档工具（标准版）」提供纳西妲（Nahida）主题美化：白绿智慧配色、四叶草点缀、圆润面板、面板沉浸式背景与浮动粒子。仅作用于标准版面板内部，不改动宿主网页。采用“增强”模式——仅覆盖主题 CSS 变量并追加装饰，不替换标准版 DOM。使用前需先安装并启用标准版脚本。
// @author       BrocadeHutHost
// @match        *://*/*
// @run-at       document-idle
// @grant        GM_addStyle
// @grant        GM_getValue
// @grant        GM_setValue
// @grant        GM_registerMenuCommand
// @homepageURL  https://github.com/BrocadeHutHost/DGUT-ULearningTakeQuizzesAssistant
// @license      AGPL-3.0-only
// ==/UserScript==


(function () {
    'use strict';

    const TAG = '[纳西妲美化]';

    const NAHIDA_BG_BASE64 = "data:image/png;base64,";

    const NAHIDA_SIDEBAR_BG_BASE64 = "data:image/png;base64,";

    const CONFIG = {
        background: GM_getValue('nahida_panel_bg', true),
        particles: GM_getValue('nahida_particles', true),
        particleCount: 6,
        waitTimeoutMs: 20000
    };

    function svgUrl(svg) {
        return 'url("data:image/svg+xml;charset=utf-8,' + encodeURIComponent(svg) + '")';
    }
    const CLOVER_WHITE = "<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'><g fill='#FFFFFF'><circle cx='50' cy='30' r='21'/><circle cx='70' cy='50' r='21'/><circle cx='50' cy='70' r='21'/><circle cx='30' cy='50' r='21'/></g><circle cx='50' cy='50' r='8' fill='#FFD700'/></svg>";
    const CLOVER_GREEN = "<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'><g fill='#6FC98E'><circle cx='50' cy='30' r='21'/><circle cx='70' cy='50' r='21'/><circle cx='50' cy='70' r='21'/><circle cx='30' cy='50' r='21'/></g><circle cx='50' cy='50' r='8' fill='#E6B422'/></svg>";
    const FAB_SVG = `
        <svg class="nahida-fab-icon" viewBox="0 0 100 100" width="46" height="46" fill="none" aria-hidden="true">
            <g class="nahida-clover">
                <circle cx="50" cy="28" r="22"/>
                <circle cx="72" cy="50" r="22"/>
                <circle cx="50" cy="72" r="22"/>
                <circle cx="28" cy="50" r="22"/>
            </g>
            <circle class="nahida-clover-core" cx="50" cy="50" r="9"/>
        </svg>`;

    const THEME_VARS_LIGHT = `
        --dgut-primary: #2E8B57 !important;
        --dgut-primary-hover: #256F46 !important;
        --dgut-on-primary: #FFFFFF !important;
        --dgut-primary-container: #D6F2E0 !important;
        --dgut-on-primary-container: #0A3B22 !important;
        --dgut-secondary-container: #EAF6EE !important;
        --dgut-on-secondary-container: #1B3D2B !important;
        --dgut-surface: #F4FBF6 !important;
        --dgut-surface-2: #EAF6EE !important;
        --dgut-surface-3: #FFFFFF !important;
        --dgut-on-surface: #1D1B20 !important;
        --dgut-on-surface-variant: #49454E !important;
        --dgut-outline: #7A9587 !important;
        --dgut-outline-variant: #D5E8DB !important;
        --dgut-error: #B3261E !important;
        --dgut-error-container: #FDECEA !important;
        --dgut-on-error-container: #7A241A !important;
        --dgut-success: #2E7D32 !important;
        --dgut-success-container: #E3F5E5 !important;
        --dgut-on-success-container: #1B5E20 !important;
        --dgut-warn: #8A5A00 !important;
        --dgut-warn-container: #FFF4D6 !important;
        --dgut-on-warn-container: #6E4B00 !important;
        --dgut-info-container: #E4F5EA !important;
        --dgut-on-info-container: #16452C !important;
        --dgut-input-bg: #EAF6EE !important;
        --dgut-hover-overlay: rgba(46,139,87,.06) !important;
        --dgut-color-scheme: light !important;
    `;

    const THEME_VARS_DARK = `
        --dgut-primary: #8FE0AC !important;
        --dgut-primary-hover: #A6EABF !important;
        --dgut-on-primary: #062B18 !important;
        --dgut-primary-container: #1E4D33 !important;
        --dgut-on-primary-container: #C8F2D8 !important;
        --dgut-secondary-container: #24382C !important;
        --dgut-on-secondary-container: #D5E8DA !important;
        --dgut-surface: #0E1813 !important;
        --dgut-surface-2: #14211A !important;
        --dgut-surface-3: #1B2C22 !important;
        --dgut-on-surface: #E6E0E9 !important;
        --dgut-on-surface-variant: #CAC4D0 !important;
        --dgut-outline: #71877A !important;
        --dgut-outline-variant: #2E4236 !important;
        --dgut-error: #F2B8B5 !important;
        --dgut-error-container: #5C1F19 !important;
        --dgut-on-error-container: #F9DEDC !important;
        --dgut-success: #A5D6A7 !important;
        --dgut-success-container: #1B4D22 !important;
        --dgut-on-success-container: #B8E5BA !important;
        --dgut-warn: #FFCE7A !important;
        --dgut-warn-container: #463200 !important;
        --dgut-on-warn-container: #FFE3A8 !important;
        --dgut-info-container: #1C3A2A !important;
        --dgut-on-info-container: #CDEBDA !important;
        --dgut-input-bg: #14211A !important;
        --dgut-hover-overlay: rgba(143,224,172,.08) !important;
        --dgut-color-scheme: dark !important;
    `;

    const STYLE_ID = 'nahida-skin-style';

    function buildCSS() {
        return `
        :root { ${THEME_VARS_LIGHT} }
        html.dgut-theme-dark { ${THEME_VARS_DARK} }

        :root {
            --nahida-radius: 18px;
            --nh-gold: #E6C36B;
            --nh-gold-2: #A6791E;
            --nh-leaf: #6FC98E;
        }

        :root { --nahida-bg-mask: linear-gradient(rgba(244,251,246,.14), rgba(244,251,246,.14)); }
        html.dgut-theme-dark { --nahida-bg-mask: linear-gradient(rgba(14,24,19,.22), rgba(14,24,19,.22)); }
        :root { --nahida-sidebar-mask: linear-gradient(rgba(16,52,34,.30), rgba(16,52,34,.30)); }
        html.dgut-theme-dark { --nahida-sidebar-mask: linear-gradient(rgba(8,26,18,.42), rgba(8,26,18,.42)); }

        #dgut-main-panel.nahida-panel-bg {
            background-color: var(--dgut-surface) !important;
            background-image: var(--nahida-bg-mask, none), var(--nahida-bg-image, none) !important;
            background-size: cover, cover !important;
            background-position: center, center !important;
            background-repeat: no-repeat, no-repeat !important;
        }
        #dgut-main-panel.nahida-panel-bg > div:not(#dgut-panel-header),
        #dgut-main-panel.nahida-panel-bg > div:nth-child(2) > div:nth-child(2),
        #dgut-main-panel.nahida-panel-bg [style*="var(--dgut-surface);"] {
            background-color: transparent !important;
            background-image: none !important;
        }
        #dgut-main-panel.nahida-panel-bg > div > div {
            background-color: transparent !important;
        }
        #dgut-main-panel.nahida-panel-bg #dgut-sidebar {
            background-image: var(--nahida-sidebar-mask, none), var(--nahida-sidebar-bg, linear-gradient(180deg, var(--dgut-surface-2), var(--dgut-surface))) !important;
            background-size: cover, cover !important;
            background-position: center, center !important;
            background-repeat: no-repeat, no-repeat !important;
        }
        #dgut-main-panel.nahida-panel-bg #dgut-panel-body {
            background: transparent !important;
        }
        #dgut-main-panel.nahida-panel-bg #dgut-status-bar {
            background: color-mix(in srgb, var(--dgut-surface-2) 52%, transparent) !important;
        }
        #dgut-main-panel.nahida-panel-bg .dgut-card {
            background: color-mix(in srgb, var(--dgut-surface-3) 48%, transparent) !important;
            -webkit-backdrop-filter: blur(3px) saturate(1.05);
            backdrop-filter: blur(3px) saturate(1.05);
        }
        #dgut-main-panel:not(.nahida-panel-bg) #dgut-panel-body { background: var(--dgut-surface); }

        #dgut-main-panel {
            border-radius: 20px !important;
            border: none !important;
            box-shadow:
                0 0 0 1px var(--nh-gold),
                0 0 0 1.5px var(--nh-gold-2),
                0 0 18px rgba(230,195,107,.34),
                0 18px 52px rgba(46,139,87,.30) !important;
            overflow: hidden !important;
        }

        #dgut-panel-header {
            background: linear-gradient(120deg, var(--dgut-primary) 0%, var(--dgut-primary-hover) 62%, #1E6B42 100%) !important;
            position: relative;
            padding-top: 13px !important;
            padding-bottom: 13px !important;
            box-shadow: inset 0 -1px 0 var(--nh-gold) !important;
        }
        #dgut-panel-header > svg { display: none !important; }
        #dgut-panel-header::before {
            content: '';
            width: 24px; height: 24px; flex: none;
            background-image: var(--nahida-clover-white);
            background-size: contain; background-repeat: no-repeat; background-position: center;
            filter: drop-shadow(0 1px 2px rgba(0,0,0,.25));
        }
        #dgut-panel-header::after {
            content: '';
            position: absolute; inset: 0;
            background: radial-gradient(140px 46px at 88% -30%, rgba(255,215,0,.38), transparent 72%);
            pointer-events: none;
        }
        #dgut-panel-header .panel-title { letter-spacing: .3px; }

        #dgut-panel-close { transition: transform .15s, background .15s !important; }
        #dgut-panel-close:hover { transform: rotate(90deg); }

        #dgut-sidebar {
            background: linear-gradient(180deg, var(--dgut-surface-2), var(--dgut-surface)) !important;
            border: none !important;
            border-radius: 14px !important;
            margin: 10px 6px 10px 10px !important;
            overflow: hidden auto !important;
            box-shadow:
                0 0 0 1px var(--nh-gold),
                0 0 0 1.5px var(--nh-gold-2),
                0 2px 10px rgba(0,0,0,.14) !important;
        }
        .dgut-nav-label { color: var(--dgut-primary) !important; opacity: .75; }
        .dgut-nav { border-radius: 12px !important; }
        .dgut-nav:hover {
            background: linear-gradient(90deg, var(--dgut-primary-container), transparent) !important;
        }
        .dgut-nav.dgut-tab-active {
            background: linear-gradient(90deg, var(--dgut-primary-container), transparent) !important;
            color: var(--dgut-primary) !important;
            box-shadow: inset 3px 0 0 var(--dgut-primary);
        }

        #dgut-panel-body { padding: 12px 14px !important; }
        #dgut-panel-footer-version { color: var(--dgut-on-surface-variant) !important; opacity: .85; }
        #dgut-status-bar { border-top: 1px solid color-mix(in srgb, var(--nh-gold) 55%, transparent) !important; }

        .dgut-card {
            border-radius: 16px !important;
            border: none !important;
            box-shadow:
                0 0 0 0.5px var(--nh-gold),
                0 0 0 1px color-mix(in srgb, var(--nh-gold-2) 55%, transparent),
                0 4px 18px rgba(46,139,87,.10) !important;
        }
        .dgut-section-title { position: relative; padding-left: 12px; }
        .dgut-section-title::before {
            content: '';
            position: absolute; left: 0; top: 50%; transform: translateY(-50%);
            width: 4px; height: 14px; border-radius: 2px;
            background: linear-gradient(180deg, var(--dgut-primary), var(--nh-gold));
        }

        .dgut-hint { border-radius: 14px !important; }

        .dgut-input, .dgut-textarea, .dgut-select { border-radius: 12px !important; }
        .dgut-input:focus, .dgut-textarea:focus, .dgut-select:focus {
            box-shadow: 0 0 0 3px rgba(46,139,87,.14) !important;
        }

        .dgut-btn { border-radius: 999px !important; transition: transform .14s, box-shadow .14s, background .14s !important; }
        .dgut-btn:not(:disabled):hover { transform: translateY(-1px); }
        .dgut-btn-primary {
            background: linear-gradient(120deg, var(--dgut-primary), var(--dgut-primary-hover)) !important;
            box-shadow: 0 2px 10px rgba(46,139,87,.35) !important;
        }
        .dgut-btn-primary:not(:disabled):hover { box-shadow: 0 4px 16px rgba(46,139,87,.5) !important; }

        .dgut-sign-course { border-radius: 12px !important; }
        .dgut-sign-course.active { box-shadow: 0 0 0 2px rgba(46,139,87,.25) inset; }

        .dgut-log { border-radius: 12px !important; }

        .dgut-tab-btn.active { border-bottom-width: 3px !important; }

        #dgut-doc-preview-box { border-radius: 12px !important; }
        #dgut-sig-canvas { border-radius: 12px !important; }

        #dgut-main-panel ::-webkit-scrollbar-thumb {
            background: linear-gradient(180deg, var(--dgut-primary), var(--nh-gold)) !important;
            border: 2px solid var(--dgut-surface) !important;
        }

        #dgut-toast-card {
            border-radius: 18px !important;
            border: none !important;
            border-left: 6px solid var(--nh-gold) !important;
            box-shadow:
                0 0 0 1px var(--nh-gold),
                0 0 0 1.5px var(--nh-gold-2),
                0 18px 52px rgba(46,139,87,.32) !important;
            background-image: radial-gradient(200px 60px at 100% 0, rgba(230,180,34,.12), transparent 70%) !important;
        }
        .dgut-toast-progress { background: linear-gradient(90deg, var(--dgut-primary), var(--nh-gold)) !important; }

        #dgut-mini-panel {
            border-radius: 50% !important;
            border: none !important;
            background: radial-gradient(circle at 34% 28%, #ffffff, var(--dgut-primary-container)) !important;
            box-shadow:
                0 0 0 1px var(--nh-gold),
                0 0 0 1.5px var(--nh-gold-2),
                0 6px 22px rgba(46,139,87,.42) !important;
            transition: box-shadow .2s, transform .2s, border-color .2s, background .2s !important;
        }
        html.dgut-theme-dark #dgut-mini-panel {
            background: radial-gradient(circle at 34% 28%, #24402F, var(--dgut-primary-container)) !important;
        }
        #dgut-mini-panel:hover {
            transform: scale(1.08) !important;
            box-shadow:
                0 0 0 1px var(--nh-gold),
                0 0 0 1.5px var(--nh-gold-2),
                0 0 20px rgba(230,195,107,.65),
                0 10px 30px rgba(46,139,87,.55) !important;
        }
        #dgut-mini-panel .nahida-clover circle { fill: var(--dgut-primary); transition: fill .2s; }
        #dgut-mini-panel .nahida-clover-core { fill: var(--nh-gold); }
        #dgut-mini-panel:hover .nahida-clover { transform-origin: 50px 50px; animation: nahidaSpin 3s linear infinite; }

        #nahida-particles {
            position: absolute; inset: 0; overflow: hidden;
            pointer-events: none; z-index: 6;
            border-radius: inherit;
        }
        .nahida-leaf {
            position: absolute; top: -60px; width: 22px; height: 22px;
            background-image: var(--nahida-leaf-uri);
            background-size: contain; background-repeat: no-repeat; background-position: center;
            opacity: .5;
            animation-name: nahidaFall;
            animation-timing-function: linear;
            animation-iteration-count: infinite;
            will-change: transform, opacity;
        }

        @keyframes nahidaFall {
            0%   { transform: translateY(-40px) rotate(0deg); opacity: 0; }
            12%  { opacity: .55; }
            100% { transform: translateY(600px) rotate(320deg); opacity: 0; }
        }
        @keyframes nahidaSpin {
            from { transform: rotate(0deg); }
            to   { transform: rotate(360deg); }
        }
        @media (prefers-reduced-motion: reduce) {
            .nahida-leaf { animation: none !important; opacity: 0 !important; }
            #dgut-mini-panel:hover .nahida-clover { animation: none !important; }
        }
        `;
    }

    function injectStyles() {
        if (document.getElementById(STYLE_ID)) return;
        const el = document.createElement('style');
        el.id = STYLE_ID;
        el.textContent = buildCSS();
        (document.head || document.documentElement).appendChild(el);
    }

    function injectSvgVars() {
        const root = document.documentElement;
        root.style.setProperty('--nahida-clover-white', svgUrl(CLOVER_WHITE));
        root.style.setProperty('--nahida-leaf-uri', svgUrl(CLOVER_GREEN));
    }

    function applyBackground() {
        const root = document.documentElement;
        const panelRaw = (NAHIDA_BG_BASE64 || '').replace(/\s+/g, '');
        const sideRaw = (NAHIDA_SIDEBAR_BG_BASE64 || '').replace(/\s+/g, '');
        const panelImg = panelRaw
            ? 'url("' + panelRaw + '")'
            : 'linear-gradient(135deg, #2E8B57 0%, #3CB371 45%, #4682B4 100%)';
        root.style.setProperty('--nahida-bg-image', panelImg);
        if (sideRaw) root.style.setProperty('--nahida-sidebar-bg', 'url("' + sideRaw + '")');
    }

    function mountParticles(panel) {
        if (!CONFIG.particles || !panel) return;
        if (panel.querySelector('#nahida-particles')) return;
        const layer = document.createElement('div');
        layer.id = 'nahida-particles';
        for (let i = 0; i < CONFIG.particleCount; i++) {
            const leaf = document.createElement('div');
            leaf.className = 'nahida-leaf';
            leaf.style.left = (Math.random() * 100).toFixed(2) + '%';
            leaf.style.animationDelay = (Math.random() * 8).toFixed(2) + 's';
            leaf.style.animationDuration = (6 + Math.random() * 5).toFixed(2) + 's';
            const scale = (0.6 + Math.random() * 0.8).toFixed(2);
            leaf.style.width = (16 * scale).toFixed(1) + 'px';
            leaf.style.height = (16 * scale).toFixed(1) + 'px';
            layer.appendChild(leaf);
        }
        panel.appendChild(layer);
    }

    function enhancePanel() {
        const panel = document.getElementById('dgut-main-panel');
        if (!panel) return;
        if (CONFIG.background) {
            applyBackground();
            panel.classList.add('nahida-panel-bg');
            paintPanelBackground(panel);
        }
        mountParticles(panel);
    }

    function paintPanelBackground(panel) {
        const raw = (NAHIDA_BG_BASE64 || '').replace(/\s+/g, '');
        const img = raw ? 'url("' + raw + '")' : 'linear-gradient(135deg, #2E8B57 0%, #3CB371 45%, #4682B4 100%)';
        const dark = document.documentElement.classList.contains('dgut-theme-dark');
        const mask = dark
            ? 'linear-gradient(rgba(14,24,19,.22), rgba(14,24,19,.22))'
            : 'linear-gradient(rgba(244,251,246,.14), rgba(244,251,246,.14))';
        panel.style.setProperty('background-color', 'transparent', 'important');
        panel.style.setProperty('background-image', mask + ', ' + img, 'important');
        panel.style.setProperty('background-size', 'cover, cover', 'important');
        panel.style.setProperty('background-position', 'center, center', 'important');
        panel.style.setProperty('background-repeat', 'no-repeat, no-repeat', 'important');
        const row = panel.children[1];
        if (row) {
            row.style.setProperty('background', 'transparent', 'important');
            row.style.setProperty('background-image', 'none', 'important');
            Array.prototype.forEach.call(row.children, function (child) {
                if (child.id === 'dgut-sidebar') return;
                child.style.setProperty('background', 'transparent', 'important');
                child.style.setProperty('background-image', 'none', 'important');
            });
        }
        const body = panel.querySelector('#dgut-panel-body');
        if (body) {
            body.style.setProperty('background', 'transparent', 'important');
            body.style.setProperty('background-image', 'none', 'important');
        }
        const status = panel.querySelector('#dgut-status-bar');
        if (status) status.style.setProperty('background', 'transparent', 'important');
    }

    function enhanceFab() {
        const mini = document.getElementById('dgut-mini-panel');
        if (!mini) return;
        if (mini.dataset.nahidaEnhanced === '1') return;
        mini.dataset.nahidaEnhanced = '1';
        mini.classList.add('nahida-fab');
        mini.innerHTML = FAB_SVG;
        if (!mini.getAttribute('title')) mini.setAttribute('title', '打开优学院助手');
    }

    function standardPresent() {
        return !!(document.getElementById('dgut-main-panel') || document.getElementById('dgut-mini-panel'));
    }

    let activated = false;
    function activate(why) {
        if (activated) return;
        activated = true;
        log('已检测到标准版（' + why + '），开始应用纳西妲美化。');
        if (CONFIG.background) applyBackground();
        enhancePanel();
        enhanceFab();
        watchDom();
    }

    let observer = null;
    function watchDom() {
        if (observer) return;
        observer = new MutationObserver(() => {
            if (document.getElementById('dgut-mini-panel')) enhanceFab();
            if (!activated && standardPresent()) { activate('DOM 变化'); return; }
            if (activated && document.getElementById('dgut-main-panel')) enhancePanel();
        });
        observer.observe(document.body || document.documentElement, { childList: true });
    }

    function waitForStandard() {
        if (standardPresent()) { activate('初始检测'); return; }
        watchDom();
        const start = Date.now();
        const timer = setInterval(() => {
            if (standardPresent()) { clearInterval(timer); activate('轮询'); return; }
            if (Date.now() - start > CONFIG.waitTimeoutMs) {
                clearInterval(timer);
                log('未检测到标准版脚本，未激活美化（仅保留无副作用样式）。');
            }
        }, 500);
    }

    function log() {
        try { console.log(TAG, ...arguments); } catch (e) {}
    }

    function registerMenus() {
        try {
            if (typeof GM_registerMenuCommand !== 'function') return;
            GM_registerMenuCommand('切换纳西妲面板背景（当前：' + (CONFIG.background ? '开' : '关') + '）', () => {
                GM_setValue('nahida_panel_bg', !CONFIG.background);
                location.reload();
            });
            GM_registerMenuCommand('切换飘落粒子（当前：' + (CONFIG.particles ? '开' : '关') + '）', () => {
                GM_setValue('nahida_particles', !CONFIG.particles);
                location.reload();
            });
        } catch (e) {}
    }

    function boot() {
        injectSvgVars();
        injectStyles();
        registerMenus();

        waitForStandard();
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', boot, { once: true });
    } else {
        boot();
    }
})();
